package com.osgst;

import java.io.IOException;
import javax.annotation.Nullable;
import lombok.extern.slf4j.Slf4j;
import okhttp3.Call;
import okhttp3.Callback;
import okhttp3.HttpUrl;
import okhttp3.MediaType;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.RequestBody;
import okhttp3.Response;

/**
 * Small asynchronous helper for writing JSON to a Firebase Realtime Database via
 * its REST API. All calls are non-blocking (OkHttp {@code enqueue}) so the game
 * thread is never held. Failures are logged and never thrown.
 */
@Slf4j
class FirebaseClient
{
	private static final MediaType JSON = MediaType.parse("application/json; charset=utf-8");

	private final OkHttpClient http;

	/** Base RTDB url, trailing slash stripped, e.g. {@code https://app-default-rtdb.firebaseio.com}. */
	private final String baseUrl;

	/** Firebase DB secret / auth token; may be empty when rules allow open write. */
	private final String secret;

	FirebaseClient(OkHttpClient http, String baseUrl, String secret)
	{
		this.http = http;
		this.baseUrl = baseUrl == null ? "" : baseUrl.trim().replaceAll("/+$", "");
		this.secret = secret == null ? "" : secret.trim();
	}

	boolean isConfigured()
	{
		return !baseUrl.isEmpty();
	}

	/**
	 * POST json to {@code path} (Firebase generates a push key). Used for timeline events.
	 */
	void post(String path, String json)
	{
		send("POST", path, json);
	}

	/**
	 * PUT json to {@code path} (overwrites the node). Used for startMarker and presence.
	 */
	void put(String path, String json)
	{
		send("PUT", path, json);
	}

	private void send(String method, String path, String json)
	{
		if (!isConfigured())
		{
			return;
		}

		HttpUrl url = url(path);
		if (url == null)
		{
			log.warn("OSGST: could not build Firebase url from base '{}' and path '{}'", baseUrl, path);
			return;
		}

		RequestBody body = RequestBody.create(JSON, json);
		Request request = new Request.Builder()
			.url(url)
			.method(method, body)
			.build();

		http.newCall(request).enqueue(new Callback()
		{
			@Override
			public void onFailure(Call call, IOException e)
			{
				log.warn("OSGST: Firebase {} {} failed: {}", method, path, e.getMessage());
			}

			@Override
			public void onResponse(Call call, Response response)
			{
				try (Response r = response)
				{
					if (!r.isSuccessful())
					{
						log.warn("OSGST: Firebase {} {} returned HTTP {}", method, path, r.code());
					}
				}
			}
		});
	}

	/**
	 * Builds {@code baseUrl + "/" + path + ".json" (+ "?auth=secret")}.
	 */
	@Nullable
	private HttpUrl url(String path)
	{
		HttpUrl parsed = HttpUrl.parse(baseUrl + "/" + path + ".json");
		if (parsed == null)
		{
			return null;
		}

		HttpUrl.Builder builder = parsed.newBuilder();
		if (!secret.isEmpty())
		{
			builder.addQueryParameter("auth", secret);
		}
		return builder.build();
	}
}

