package com.osgst;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.ConfigSection;

@ConfigGroup(OsgsConfig.GROUP)
public interface OsgsConfig extends Config
{
	String GROUP = "osgst";

	@ConfigSection(
		name = "Third-party data notice",
		description = "This plugin sends your OSRS display name, boss kill counts and loot data (item "
			+ "name, item ID, quantity and GE value, plus the name and type of what dropped it) to a "
			+ "personal Firebase Realtime Database (a third-party server not controlled by RuneLite) "
			+ "that you configure below. If you set a room code, that code is also sent, as part of "
			+ "the destination path. Nothing is sent until you enter a Firebase URL. No data leaves "
			+ "your client if 'Enable tracking' is off. The plugin never reads other players' data and "
			+ "never modifies the game.",
		position = 0,
		closedByDefault = false
	)
	String disclosureSection = "disclosure";

	@ConfigSection(
		name = "Firebase connection",
		description = "Where session data is sent. Leave the URL blank to disable all network sending.",
		position = 1,
		closedByDefault = false
	)
	String connectionSection = "connection";

	@ConfigItem(
		keyName = "firebaseUrl",
		name = "Firebase RTDB URL",
		description = "Your Firebase Realtime Database URL, e.g. https://your-app-default-rtdb.firebaseio.com "
			+ "Leave blank to disable all sending.",
		position = 1,
		section = connectionSection
	)
	default String firebaseUrl()
	{
		return "";
	}

	@ConfigItem(
		keyName = "firebaseSecret",
		name = "Firebase secret",
		description = "Optional Firebase database secret / auth token. Leave blank if your database rules "
			+ "allow open writes. Appended as ?auth= to requests.",
		position = 2,
		section = connectionSection,
		secret = true
	)
	default String firebaseSecret()
	{
		return "";
	}

	@ConfigItem(
		keyName = "playerName",
		name = "Player name override",
		description = "Override the name reported to the web tool. Leave blank to use your logged-in "
			+ "display name.",
		position = 3,
		section = connectionSection
	)
	default String playerName()
	{
		return "";
	}

	@ConfigItem(
		keyName = "roomCode",
		name = "Room code (optional)",
		description = "Leave this blank unless you have been given a room code — blank is the normal "
			+ "setting and keeps everything working exactly as before. When set, session data is sent "
			+ "to rooms/<code>/ instead of the shared default path, so only people using the same code "
			+ "see it. The code is lowercased, anything outside a-z 0-9 - _ is removed (a space in "
			+ "\"My Room\" makes it \"myroom\"), and it is cut off after 24 characters; the plugin "
			+ "tells you in chat what your code became. 'Use dev database paths' has no effect while a "
			+ "room code is set — test with a throwaway code instead.",
		position = 4,
		section = connectionSection
	)
	default String roomCode()
	{
		return "";
	}

	@ConfigItem(
		keyName = "trackingEnabled",
		name = "Enable tracking",
		description = "Master on/off switch. When off, no kills, loot or presence are sent anywhere.",
		position = 4,
		warning = "This uploads your OSRS display name, boss kill counts and loot data (item name, item "
			+ "ID, quantity and GE value) to the third-party Firebase database you configured. Only "
			+ "enable it if you consent to that. Continue?"
	)
	default boolean trackingEnabled()
	{
		return true;
	}

	@ConfigItem(
		keyName = "presenceEnabled",
		name = "Send presence heartbeat",
		description = "Every 60 seconds, send a timestamp so the web tool can show you as online.",
		position = 5
	)
	default boolean presenceEnabled()
	{
		return true;
	}

	@ConfigItem(
		keyName = "customBosses",
		name = "Custom bosses / NPCs",
		description = "Comma-separated list of additional boss or NPC names to track beyond the built-in "
			+ "presets. Names must match the in-game spelling.",
		position = 6
	)
	default String customBosses()
	{
		return "";
	}

	@ConfigItem(
		keyName = "markSessionStart",
		name = "Mark Session Start",
		description = "Tick this to stamp the current time as the session start in Firebase. The "
			+ "checkbox does not untick itself, so you may need to click it twice. The confirmation "
			+ "is the '[OSGST] Game session start marked.' line in your chat, not the state of the "
			+ "checkbox.",
		position = 7
	)
	default boolean markSessionStart()
	{
		return false;
	}

	@ConfigItem(
		keyName = "devPaths",
		name = "Use dev database paths",
		description = "Write to gamenight_dev/plugin/* instead of gamenight/plugin/*, so plugin changes "
			+ "can be tested against the same database without touching live session data. Leave off "
			+ "unless you are developing the plugin. Has no effect while a room code is set — a "
			+ "throwaway room code is the dev sandbox for room paths.",
		position = 8,
		section = connectionSection
	)
	default boolean devPaths()
	{
		return false;
	}
}

