import net.runelite.client.plugins.loottracker.LootReceived;
import net.runelite.http.api.loottracker.LootRecordType;
import okhttp3.OkHttpClient;

@Slf4j
@PluginDescriptor(
	name = "OSRS Game Session Tracker",
	description = "Sends boss kills and loot to your personal Firebase for the OSRS Game Session Tracker web tool",
	tags = {"loot", "kills", "tracker", "session", "game", "night"}
)
public class OsgsPlugin extends Plugin
{
	/**
	 * Firebase path roots. Everything is written under {@code <root>/} — the existing tool data is
	 * never touched. {@link OsgsConfig#devPaths()} swaps the live root for the dev one so plugin
	 * changes can be verified against the same database without writing into live session data.
	 */
	private static final String ROOT_LIVE = "gamenight/plugin";
	private static final String ROOT_DEV = "gamenight_dev/plugin";

	/**
	 * Root for the opt-in room system. When {@link OsgsConfig#roomCode()} sanitizes to a non-empty
	 * code, every write moves under {@code rooms/<code>/} and the {@code gamenight*} roots are not
	 * written at all. A blank code is the default and reproduces v1.2.0 behaviour exactly.
	 */
	private static final String ROOT_ROOM = "rooms";

	/** Room codes are truncated to this many characters after sanitization. */
	static final int ROOM_CODE_MAX_LENGTH = 24;

	private static final long HEARTBEAT_SECONDS = 60L;

	/**
	 * "Your Kree'arra kill count is: 47."
	 * <p>
	 * Only standard boss kills use this wording. Several entries in {@link #BOSS_NAMES} are raids
	 * or skilling/minigame activities that announce completions differently ("Your completed
	 * Chambers of Xeric count is: 5.", "Your subdued Wintertodt count is: 5.", "Your Gauntlet
	 * completion count is: 5.", "Your Barrows chest count is: 5."). Those are deliberately not
	 * matched here — they are tracked through the loot events instead, which is sufficient for the
	 * web tool. See the notes on {@link #BOSS_NAMES} and {@link #BOSS_ALIASES}.
	 */
	static final Pattern KILL_COUNT_PATTERN = Pattern.compile("Your (.+) kill count is: (\\d+)\\.");

	/**
	 * The web tool's preset list (the {@code n:} display names from its {@code BOSSES[]} array),
	 * kept in the tool's own order. These are the canonical names written to Firebase, so they must
	 * stay byte-identical to the tool's display names or its boss cards will not group events.
	 * "Custom" is a placeholder and never matches chat.
	 * <p>
	 * A handful of these never match the in-game text directly — "Bandos" is announced as
	 * "General Graardor", "Barrows Chests" arrives as "Barrows", and so on. {@link #BOSS_ALIASES}
	 * maps the in-game wording onto these display names.
	 */
	private static final List<String> BOSS_NAMES = Arrays.asList(
		// Original 16 presets, in the tool's original order.
		"Kree'arra",
		"Vet'ion",
		"Vorkath",
		"Zulrah",
		"Tormented Demon",
		"Abyssal Sire",
		"Cerberus",
		"Bandos",
		"Kraken",
		"TzTok-Jad",
		"Sarachnis",
		"Chaos Elemental",
		"Dagannoth Rex",
		"Corporeal Beast",
		"Nightmare",
		"Custom",
		// Expanded list (2026-07-28) covering the rest of the hiscores boss/activity table.
		"Amoxliatl",
		"Araxxor",
		"Artio",
		"Barrows Chests",
		"Bryophyta",
		"Callisto",
		"Calvar'ion",
		"Chambers of Xeric",
		"Chambers of Xeric: Challenge Mode",
		"Chaos Fanatic",
		"Commander Zilyana",
		"Crazy Archaeologist",
		"Dagannoth Prime",
		"Dagannoth Supreme",
		"Deranged Archaeologist",
		"Doom of Mokhaiotl",
		"Duke Sucellus",
		"Giant Mole",
		"Grotesque Guardians",
		"Hespori",
		"Kalphite Queen",
		"King Black Dragon",
		"K'ril Tsutsaroth",
		"Lunar Chests",
		"Mimic",
		"Nex",
		"Phosani's Nightmare",
		"Obor",
		"Phantom Muspah",
		"Scorpia",
		"Scurrius",
		"Shellbane Gryphon",
		"Skotizo",
		"Sol Heredit",
		"Spindel",
		"Tempoross",
		"The Gauntlet",
		"The Corrupted Gauntlet",
		"The Hueycoatl",
		"The Leviathan",
		"The Royal Titans",
		"The Whisperer",
		"Theatre of Blood",
		"Theatre of Blood: Hard Mode",
		"Thermonuclear Smoke Devil",
		"Tombs of Amascut",
		"Tombs of Amascut: Expert Mode",
		"TzKal-Zuk",
		"Vardorvis",
		"Venenatis",
		"Wintertodt",
		"Yama",
		"Zalcano",
		"Alchemical Hydra"
	);

	/**
	 * In-game wording -> canonical display name, for the presets whose chat text or NPC/event name
	 * differs from the tool's {@code n:} value. Everything not listed here matches directly.
	 * <p>
	 * The loot-event names below were read out of RuneLite's own {@code LootTrackerPlugin}
	 * constants, so they track what {@code LootReceived} actually posts.
	 * <p>
	 * Note on the difficulty variants ("Chambers of Xeric: Challenge Mode", "Theatre of Blood: Hard
	 * Mode", "Tombs of Amascut: Expert Mode"): RuneLite posts raid loot under the base raid name
	 * only, with no mode suffix, so those three entries can never match an incoming event. They are
	 * kept so the plugin list mirrors the tool's, but in practice their kills and loot land on the
	 * base raid entry.
	 */
	private static final Map<String, String> BOSS_ALIASES = buildAliases();

	private static Map<String, String> buildAliases()
	{
		final Map<String, String> aliases = new HashMap<>();
		// Chat/NPC name differs from the tool's display name.
		aliases.put("General Graardor", "Bandos");
		aliases.put("The Nightmare", "Nightmare");
		aliases.put("The Mimic", "Mimic");
		// Grotesque Guardians drop as the NPC "Dusk"; the kill-count line says "Grotesque Guardians".
		aliases.put("Dusk", "Grotesque Guardians");
		// The Gauntlet's loot comes from the Hunllef, not from an event named after the raid.
		aliases.put("Crystalline Hunllef", "The Gauntlet");
		aliases.put("Corrupted Hunllef", "The Corrupted Gauntlet");
		// Chest/minigame loot event names, per RuneLite's LootTrackerPlugin.
		aliases.put("Barrows", "Barrows Chests");
		aliases.put("Lunar Chest", "Lunar Chests");
		aliases.put("Fortis Colosseum", "Sol Heredit");
		aliases.put("Supply crate (Wintertodt)", "Wintertodt");
		aliases.put("Reward cart (Wintertodt)", "Wintertodt");
		aliases.put("Reward pool (Tempoross)", "Tempoross");
		aliases.put("Casket (Tempoross)", "Tempoross");
		return aliases;
	}

	@Inject
	private Client client;

	@Inject
	private ClientThread clientThread;

	@Inject
	private OsgsConfig config;

	@Inject
	private ConfigManager configManager;

	@Inject
	private ItemManager itemManager;

	@Inject
	private OkHttpClient okHttpClient;

	/** Lowercase in-game name -> canonical display name used in Firebase. Rebuilt on config change. */
	private final Map<String, String> trackedBosses = new HashMap<>();

	private volatile FirebaseClient firebase;
	private volatile String playerName;

	private ScheduledExecutorService heartbeatExecutor;
	private ScheduledFuture<?> heartbeatFuture;

	@Provides
	OsgsConfig provideConfig(ConfigManager manager)
	{
		return manager.getConfig(OsgsConfig.class);
	}

	@Override
	protected void startUp()
	{
		rebuildBosses();
		rebuildFirebase();
		resolvePlayerName();

		heartbeatExecutor = Executors.newSingleThreadScheduledExecutor();
		heartbeatFuture = heartbeatExecutor.scheduleAtFixedRate(
			this::sendHeartbeat, HEARTBEAT_SECONDS, HEARTBEAT_SECONDS, TimeUnit.SECONDS);

		if (firebase == null || !firebase.isConfigured())
		{
			log.warn("OSGST: no Firebase URL configured — sending is disabled until one is set.");
		}
		log.info("OSRS Game Session Tracker started");
	}

	@Override
	protected void shutDown()
	{
		if (heartbeatFuture != null)
		{
			heartbeatFuture.cancel(true);
			heartbeatFuture = null;
		}
		if (heartbeatExecutor != null)
		{
			heartbeatExecutor.shutdownNow();
			heartbeatExecutor = null;
		}
		trackedBosses.clear();
		firebase = null;
		playerName = null;
		log.info("OSRS Game Session Tracker stopped");
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{
		if (!OsgsConfig.GROUP.equals(event.getGroup()))
		{
			return;
		}

		switch (event.getKey())
		{
			case "firebaseUrl":
			case "firebaseSecret":
				rebuildFirebase();
				break;
			case "customBosses":
				rebuildBosses();
				break;
			case "playerName":
				resolvePlayerName();
				break;
			case "roomCode":
				announceRoomCode(event.getNewValue());
				break;
			case "markSessionStart":
				if (Boolean.parseBoolean(event.getNewValue()))
				{
					markSessionStart();
					// Reset the checkbox so it behaves like a momentary button.
					configManager.setConfiguration(OsgsConfig.GROUP, "markSessionStart", false);
				}
				break;
			default:
				break;
		}
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		if (event.getGameState() == GameState.LOGGED_IN)
		{
			resolvePlayerName();
		}
	}

	@Subscribe
	public void onChatMessage(ChatMessage event)
	{
		if (!config.trackingEnabled())
		{
			return;
		}

		final Matcher matcher = KILL_COUNT_PATTERN.matcher(event.getMessage());
		if (!matcher.find())
		{
			return;
		}

		final String canonical = normalizeBoss(matcher.group(1));
		if (canonical == null)
		{
			return;
		}

		final int kc;
		try
		{
			kc = Integer.parseInt(matcher.group(2));
		}
		catch (NumberFormatException e)
		{
			return;
		}

		final JsonObject payload = new JsonObject();
		payload.addProperty("type", "kill");
		payload.addProperty("player", playerName);
		payload.addProperty("bossName", canonical);
		payload.addProperty("ts", System.currentTimeMillis());
		payload.addProperty("kc", kc);
		postTimeline(payload);
	}

	/**
	 * {@link LootReceived} is the single authoritative loot event for this plugin — do not add a
	 * second loot subscriber.
	 * <p>
	 * RuneLite's Loot Tracker funnels every loot source through its own {@code addLoot(...)}, which
	 * re-broadcasts the drop as a {@link LootReceived}. That makes it a superset: it covers NPC
	 * kills (which also post {@code NpcLootReceived} separately) as well as the chest/event sources
	 * such as raids, Barrows, and Wintertodt crates that never post an NPC event at all.
	 * <p>
	 * Subscribing to {@code NpcLootReceived} as well means a boss kill is handled twice and every
	 * item is written to Firebase twice, which is exactly what happened in production (a single
	 * Zulrah drop produced two rows for each of its three items). That subscriber has been removed.
	 * <p>
	 * Trade-off worth knowing: because this event originates in the Loot Tracker plugin, loot is
	 * only recorded while RuneLite's Loot Tracker is enabled. Kill-count tracking is unaffected.
	 */
	@Subscribe
	public void onLootReceived(LootReceived event)
	{
		handleLoot(event.getName(), event.getType(), event.getItems());
	}

	/**
	 * Runs on the client thread (the event is posted there), so
	 * {@link ItemManager#getItemComposition(int)} is safe to call directly.
	 * <p>
	 * Every loot event is sent, whatever its source. Boss-list matching is an enrichment field
	 * ({@code bossName}), not a gate — slayer trash, superior spawns and other off-list sources are
	 * reported with {@code bossName: null} and grouped dashboard-side from {@code source}.
	 */
	private void handleLoot(String sourceName, @Nullable LootRecordType sourceType,
		Collection<ItemStack> stacks)
	{
		if (!config.trackingEnabled())
		{
			return;
		}

		final JsonArray items = new JsonArray();
		for (ItemStack stack : stacks)
		{
			final int id = stack.getId();
			final int qty = stack.getQuantity();
			final String name = itemManager.getItemComposition(id).getName();
			// "gp" is the PER-UNIT GE price, matching the Firebase schema {name, qty, gp}.
			// The web tool multiplies by qty itself, so multiplying here too inflated stack values
			// by a factor of qty (200 law runes stored as 24,000 each, displayed as 4.8M).
			final long gp = itemManager.getItemPrice(id);

			items.add(buildLootItem(name, qty, gp, id));
		}

		if (items.size() == 0)
		{
			return;
		}

		postTimeline(buildLootPayload(playerName, sourceName, sourceType,
			normalizeBoss(sourceName), System.currentTimeMillis(), items));
	}

	/**
	 * Builds one entry of the {@code items} array. Pure and static so the schema contract shared
	 * with the web tool can be unit tested.
	 * <p>
	 * {@code itemId} (added in 1.3.0) is appended after the three original keys, so the
	 * {@code {name, qty, gp}} prefix stays byte-identical to what v1.2.0 wrote. It is the
	 * RuneLite/OSRS item ID, which lets the dashboard resolve icons and per-item overrides exactly
	 * instead of by name. It is omitted entirely when no positive ID is available, rather than
	 * written as a placeholder {@code 0} — Firebase drops absent keys, and the dashboard treats a
	 * missing {@code itemId} as "use the name-based path", which is also what every manually
	 * entered drop will always look like.
	 */
	static JsonObject buildLootItem(@Nullable String name, int qty, long gp, int itemId)
	{
		final JsonObject item = new JsonObject();
		item.addProperty("name", name);
		item.addProperty("qty", qty);
		item.addProperty("gp", gp);
		if (itemId > 0)
		{
			item.addProperty("itemId", itemId);
		}
		return item;
	}

	/**
	 * Builds the {@code loot} timeline payload. Pure and static so the schema contract shared with
	 * the web tool can be unit tested. Key order matches the contract document.
	 * <p>
	 * {@code bossName} is written as JSON {@code null} when the source is not on the boss list.
	 * Firebase drops null-valued keys on write, so the stored event simply has no {@code bossName} —
	 * which is what the dashboard already expects for an unmatched source.
	 */
	static JsonObject buildLootPayload(@Nullable String player, @Nullable String sourceName,
		@Nullable LootRecordType sourceType, @Nullable String bossName, long ts, JsonArray items)
	{
		final JsonObject payload = new JsonObject();
		payload.addProperty("type", "loot");
		payload.addProperty("player", player);
		payload.addProperty("source", sourceName);
		payload.addProperty("sourceType", (sourceType == null ? LootRecordType.UNKNOWN : sourceType).name());
		payload.addProperty("bossName", bossName);
		payload.addProperty("ts", ts);
		payload.add("items", items);
		return payload;
	}

	/**
	 * Resolves the root every write hangs off. Pure and static so the live/dev/room split can be
	 * unit tested.
	 * <p>
	 * A room code wins over the dev toggle: rooms are a separate namespace with no live data in it
	 * yet, so the dev sandbox for a room path is simply a throwaway code. A blank — or entirely
	 * illegal — room code falls back to the live/dev roots, which is the default and the exact
	 * v1.2.0 behaviour.
	 */
	static String pathRoot(boolean dev, @Nullable String rawRoomCode)
	{
		final String code = sanitizeRoomCode(rawRoomCode);
		if (code != null)
		{
			return ROOT_ROOM + "/" + code;
		}
		return dev ? ROOT_DEV : ROOT_LIVE;
	}

	static String pathTimeline(boolean dev, @Nullable String rawRoomCode)
	{
		return pathRoot(dev, rawRoomCode) + "/timeline";
	}

	static String pathStartMarker(boolean dev, @Nullable String rawRoomCode)
	{
		return pathRoot(dev, rawRoomCode) + "/session/startMarker";
	}

	static String pathPresence(boolean dev, @Nullable String rawRoomCode)
	{
		return pathRoot(dev, rawRoomCode) + "/presence";
	}

	/**
	 * Normalizes a user-typed room code into something usable as a Firebase path key, or
	 * {@code null} when nothing usable is left.
	 * <p>
	 * Firebase keys may not contain {@code . # $ [ ] /}, and a code that ends up in a URL should
	 * not need escaping either, so rather than blacklisting those six characters this whitelists
	 * {@code [a-z0-9-_]}. The rules, in order:
	 * <ol>
	 *     <li>trim surrounding whitespace;</li>
	 *     <li>lowercase using {@link Locale#ROOT}, so a Turkish locale cannot turn {@code I} into a
	 *     dotless {@code i} that is then stripped — codes are case-insensitive, so {@code "ABC"}
	 *     and {@code "abc"} are the same room;</li>
	 *     <li>strip every character outside {@code [a-z0-9-_]} — an interior space, a dot or a
	 *     slash is dropped, never escaped and never left to break the path;</li>
	 *     <li>truncate to {@link #ROOM_CODE_MAX_LENGTH} characters.</li>
	 * </ol>
	 * If nothing survives ({@code ""}, {@code "..."}, {@code "///"}), the result is {@code null}
	 * and the caller falls back to the legacy root — a code that sanitizes away is treated as no
	 * code, never as an empty path segment.
	 */
	@Nullable
	static String sanitizeRoomCode(@Nullable String raw)
	{
		if (raw == null)
		{
			return null;
		}
		final String lower = raw.trim().toLowerCase(Locale.ROOT);
		final StringBuilder code = new StringBuilder(ROOM_CODE_MAX_LENGTH);
		for (int i = 0; i < lower.length() && code.length() < ROOM_CODE_MAX_LENGTH; i++)
		{
			final char c = lower.charAt(i);
			if ((c >= 'a' && c <= 'z') || (c >= '0' && c <= '9') || c == '-' || c == '_')
			{
				code.append(c);
			}
		}
		return code.length() == 0 ? null : code.toString();
	}

	private void postTimeline(JsonObject payload)
	{
		if (playerName == null)
		{
			return;
		}
		final FirebaseClient fb = firebase;
		if (fb == null || !fb.isConfigured())
		{
			return;
		}
		fb.post(pathTimeline(config.devPaths(), config.roomCode()), payload.toString());
	}

	private void sendHeartbeat()
	{
		if (!config.trackingEnabled() || !config.presenceEnabled())
		{
			return;
		}
		final String name = playerName;
		if (name == null)
		{
			return;
		}
		final FirebaseClient fb = firebase;
		if (fb == null || !fb.isConfigured())
		{
			return;
		}
		fb.put(pathPresence(config.devPaths(), config.roomCode()) + "/" + sanitizeKey(name),
			Long.toString(System.currentTimeMillis()));
	}

	private void markSessionStart()
	{
		final FirebaseClient fb = firebase;
		if (fb == null || !fb.isConfigured())
		{
			sendChatMessage("Set a Firebase URL before marking a session start.");
			return;
		}
		fb.put(pathStartMarker(config.devPaths(), config.roomCode()),
			Long.toString(System.currentTimeMillis()));
		sendChatMessage("Game session start marked.");
	}

	/**
	 * Resolves and caches the reported player name (config override, else logged-in display name).
	 * Reads game state, so it must run on the client thread.
	 */
	private void resolvePlayerName()
	{
		final String override = config.playerName().trim();
		if (!override.isEmpty())
		{
			playerName = override;
			return;
		}

		clientThread.invoke(() ->
		{
			final Player local = client.getLocalPlayer();
			if (local != null && local.getName() != null)
			{
				playerName = local.getName();
			}
		});
	}

	private void rebuildFirebase()
	{
		firebase = new FirebaseClient(okHttpClient, config.firebaseUrl(), config.firebaseSecret());
	}

	private void rebuildBosses()
	{
		trackedBosses.clear();
		trackedBosses.putAll(buildTrackedBosses(config.customBosses()));
	}

	/**
	 * Builds the lowercase-name -> canonical-name lookup from the built-in presets and their
	 * in-game aliases, plus a comma-separated list of custom names. Custom names are applied last
	 * so a user can still override a preset. Pure and static so it can be unit tested.
	 */
	static Map<String, String> buildTrackedBosses(String customCsv)
	{
		final Map<String, String> tracked = new HashMap<>();
		for (String preset : BOSS_NAMES)
		{
			if (!"Custom".equalsIgnoreCase(preset))
			{
				tracked.put(preset.toLowerCase(), preset);
			}
		}
		for (Map.Entry<String, String> alias : BOSS_ALIASES.entrySet())
		{
			tracked.put(alias.getKey().toLowerCase(), alias.getValue());
		}
		if (customCsv != null)
		{
			for (String custom : customCsv.split(","))
			{
				final String trimmed = custom.trim();
				if (!trimmed.isEmpty())
				{
					tracked.put(trimmed.toLowerCase(), trimmed);
				}
			}
		}
		return tracked;
	}

	/**
	 * Case-insensitive lookup of a raw in-game name against a tracked list.
	 * Returns the canonical display name, or null if the source is not tracked.
	 */
	@Nullable
	static String normalizeBoss(Map<String, String> tracked, @Nullable String raw)
	{
		if (raw == null)
		{
			return null;
		}
		return tracked.get(raw.trim().toLowerCase());
	}

	@Nullable
	private String normalizeBoss(@Nullable String raw)
	{
		return normalizeBoss(trackedBosses, raw);
	}

	/**
	 * Sanitization is lossy, so tell the player what their code actually became. Typing "My Room",
	 * silently landing in "myroom", and never meeting the friend who typed "my-room" is exactly the
	 * failure this is here to make visible.
	 */
	private void announceRoomCode(@Nullable String raw)
	{
		final String code = sanitizeRoomCode(raw);
		if (code == null)
		{
			log.info("OSGST: room code cleared - writing to the default path.");
			sendChatMessage("Room code cleared. Writing to the default path.");
			return;
		}
		final String root = ROOT_ROOM + "/" + code;
		log.info("OSGST: room code set - writing to {}/", root);
		sendChatMessage("Room code set to '" + code + "'. Writing to " + root + "/");
	}

	private void sendChatMessage(String message)
	{
		clientThread.invoke(() ->
			client.addChatMessage(ChatMessageType.GAMEMESSAGE, "", "[OSGST] " + message, null));
	}

	/** Firebase keys may not contain . # $ [ ] / — replace anything unusual so presence paths are valid. */
	private static String sanitizeKey(String name)
	{
		// OSRS display names use a non-breaking space (U+00A0); normalise it to a plain space.
		return name.replace((char) 0xA0, ' ').replaceAll("[.#$\\[\\]/]", "_");
	}
}

