import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import com.google.gson.JsonArray;
import com.google.gson.JsonObject;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Map;
import net.runelite.http.api.loottracker.LootRecordType;
import org.junit.Test;

/**
 * Locks the {@code loot} payload to the schema contract shared verbatim with the web tool
 * (see {@code PLUGIN_KICKOFF_loot_redesign.md} — "Schema contract"). The dashboard is built and
 * shipped against that document independently, so a change here that isn't mirrored there breaks
 * the two sides silently.
 */
public class OsgsLootPayloadTest
{
	private final Map<String, String> tracked = OsgsPlugin.buildTrackedBosses("");

	@Test
	public void offListSourceMatchesTheSchemaContractByteForByte()
	{
		// The exact example from the contract document. "Cave horror" is slayer trash: not on the
		// boss list, so bossName is null — but the event is still sent, which is the whole point of
		// the redesign.
		final JsonObject payload = OsgsPlugin.buildLootPayload(
			"Golddcaleb", "Cave horror", LootRecordType.NPC,
			OsgsPlugin.normalizeBoss(tracked, "Cave horror"), 1234567890L,
			items(OsgsPlugin.buildLootItem("Big bones", 1, 320, 532)));

		assertEquals("{\"type\":\"loot\",\"player\":\"Golddcaleb\",\"source\":\"Cave horror\","
			+ "\"sourceType\":\"NPC\",\"bossName\":null,\"ts\":1234567890,"
			+ "\"items\":[{\"name\":\"Big bones\",\"qty\":1,\"gp\":320,\"itemId\":532}]}",
			payload.toString());
	}

	@Test
	public void keyOrderMatchesTheContract()
	{
		final JsonObject payload = OsgsPlugin.buildLootPayload(
			"Golddcaleb", "Zulrah", LootRecordType.NPC, "Zulrah", 1L, items());
		assertEquals(Arrays.asList("type", "player", "source", "sourceType", "bossName", "ts", "items"),
			new ArrayList<>(payload.keySet()));
	}

	@Test
	public void matchedBossKeepsBossNameAndReportsTheRawSource()
	{
		// bossName still goes through normalizeBoss() and still carries the tool's display name;
		// source is the unmodified in-game name, which for Bandos differs from the display name.
		final JsonObject payload = OsgsPlugin.buildLootPayload(
			"Golddcaleb", "General Graardor", LootRecordType.NPC,
			OsgsPlugin.normalizeBoss(tracked, "General Graardor"), 1L,
			items(item("Bandos chestplate", 1, 15_000_000)));

		assertEquals("General Graardor", payload.get("source").getAsString());
		assertEquals("Bandos", payload.get("bossName").getAsString());
		assertEquals("NPC", payload.get("sourceType").getAsString());
	}

	@Test
	public void chestSourcesAreReportedAsEvents()
	{
		// Raids/chests post as EVENT with the chest's own name; the alias table still resolves the
		// boss name, so both fields stay useful.
		final JsonObject payload = OsgsPlugin.buildLootPayload(
			"Golddcaleb", "Barrows", LootRecordType.EVENT,
			OsgsPlugin.normalizeBoss(tracked, "Barrows"), 1L, items(item("Dharok's helm", 1, 100)));

		assertEquals("Barrows", payload.get("source").getAsString());
		assertEquals("EVENT", payload.get("sourceType").getAsString());
		assertEquals("Barrows Chests", payload.get("bossName").getAsString());
	}

	@Test
	public void everyLootRecordTypeSerializesToItsContractString()
	{
		// The contract allows exactly these five values; LootRecordType.name() is what produces them.
		final String[] expected = {"NPC", "PLAYER", "EVENT", "PICKPOCKET", "UNKNOWN"};
		final String[] actual = new String[LootRecordType.values().length];
		for (int i = 0; i < LootRecordType.values().length; i++)
		{
			actual[i] = OsgsPlugin.buildLootPayload("p", "s", LootRecordType.values()[i], null, 1L, items())
				.get("sourceType").getAsString();
		}
		assertEquals(Arrays.asList(expected), Arrays.asList(actual));
	}

	@Test
	public void missingSourceTypeFallsBackToUnknown()
	{
		// sourceType must always be present and always be one of the five contract strings, so a
		// null type from the event degrades to UNKNOWN rather than to JSON null.
		final JsonObject payload = OsgsPlugin.buildLootPayload("p", "Goblin", null, null, 1L, items());
		assertEquals("UNKNOWN", payload.get("sourceType").getAsString());
	}

	@Test
	public void sourceAndSourceTypeArePresentEvenWhenBossNameIsNull()
	{
		final JsonObject payload = OsgsPlugin.buildLootPayload(
			"Golddcaleb", "Nechryael", LootRecordType.NPC,
			OsgsPlugin.normalizeBoss(tracked, "Nechryael"), 1L, items(item("Rune boots", 1, 12_000)));

		assertTrue(payload.get("bossName").isJsonNull());
		assertEquals("Nechryael", payload.get("source").getAsString());
		assertEquals("NPC", payload.get("sourceType").getAsString());
		assertEquals("loot", payload.get("type").getAsString());
		assertEquals(1, payload.getAsJsonArray("items").size());
	}

	@Test
	public void itemIdIsAppendedAfterTheThreeOriginalKeys()
	{
		// Additive only: the {name, qty, gp} prefix is byte-identical to v1.2.0, so a dashboard that
		// has never heard of itemId reads exactly what it read before.
		final JsonObject item = OsgsPlugin.buildLootItem("Bandos chestplate", 1, 15_000_000, 11832);
		assertEquals("{\"name\":\"Bandos chestplate\",\"qty\":1,\"gp\":15000000,\"itemId\":11832}",
			item.toString());
		assertEquals(Arrays.asList("name", "qty", "gp", "itemId"), new ArrayList<>(item.keySet()));
	}

	@Test
	public void itemIdIsOmittedRatherThanWrittenAsAPlaceholderZero()
	{
		// Firebase drops absent keys, and the dashboard's name-based path is keyed on key absence.
		// Writing a placeholder 0 would look like a real item ID and resolve to the wrong icon.
		for (int noId : new int[]{0, -1, Integer.MIN_VALUE})
		{
			final JsonObject item = OsgsPlugin.buildLootItem("Big bones", 1, 320, noId);
			assertFalse("itemId " + noId + " should be omitted", item.has("itemId"));
			assertEquals("{\"name\":\"Big bones\",\"qty\":1,\"gp\":320}", item.toString());
		}
	}

	@Test
	public void devToggleSwitchesEveryPathOffTheLiveRoot()
	{
		assertEquals("gamenight/plugin/timeline", OsgsPlugin.pathTimeline(false, ""));
		assertEquals("gamenight/plugin/session/startMarker", OsgsPlugin.pathStartMarker(false, ""));
		assertEquals("gamenight/plugin/presence", OsgsPlugin.pathPresence(false, ""));

		assertEquals("gamenight_dev/plugin/timeline", OsgsPlugin.pathTimeline(true, ""));
		assertEquals("gamenight_dev/plugin/session/startMarker", OsgsPlugin.pathStartMarker(true, ""));
		assertEquals("gamenight_dev/plugin/presence", OsgsPlugin.pathPresence(true, ""));
	}

	@Test
	public void blankRoomCodeIsByteForByteTheV120Behaviour()
	{
		// The default config value is "", and every user who never touches the new field must keep
		// landing on exactly the path v1.2.0 wrote to.
		for (String blank : new String[]{null, "", "   ", "...", "///", "#$[]"})
		{
			assertEquals("blank code: " + blank, "gamenight/plugin/timeline",
				OsgsPlugin.pathTimeline(false, blank));
			assertEquals("blank code: " + blank, "gamenight_dev/plugin/timeline",
				OsgsPlugin.pathTimeline(true, blank));
		}
	}

	@Test
	public void populatedRoomCodeMovesEveryPathUnderRooms()
	{
		assertEquals("rooms/friday/timeline", OsgsPlugin.pathTimeline(false, "friday"));
		assertEquals("rooms/friday/session/startMarker", OsgsPlugin.pathStartMarker(false, "friday"));
		assertEquals("rooms/friday/presence", OsgsPlugin.pathPresence(false, "friday"));
	}

	@Test
	public void roomCodeWinsOverTheDevToggle()
	{
		// Documented precedence: rooms are their own namespace, so a throwaway code is the dev
		// sandbox. The dev toggle must not silently produce a third, undocumented root.
		assertEquals("rooms/friday/timeline", OsgsPlugin.pathTimeline(true, "friday"));
	}

	@Test
	public void roomCodeSanitizationFollowsTheDocumentedRules()
	{
		// Trim, lowercase, strip anything outside [a-z0-9-_], truncate at 24.
		assertEquals("friday", OsgsPlugin.sanitizeRoomCode("  Friday  "));
		assertEquals("friday", OsgsPlugin.sanitizeRoomCode("FRIDAY"));
		assertEquals("myroom", OsgsPlugin.sanitizeRoomCode("My Room"));
		assertEquals("my-room_2", OsgsPlugin.sanitizeRoomCode("my-room_2"));
		// The six characters Firebase forbids in a key are removed, not escaped and not kept.
		assertEquals("abc", OsgsPlugin.sanitizeRoomCode("a.b#c"));
		assertEquals("abc", OsgsPlugin.sanitizeRoomCode("a/b$c"));
		assertEquals("abc", OsgsPlugin.sanitizeRoomCode("a[b]c"));

		// Nothing usable left -> null, so the caller falls back to the legacy root rather than
		// building "rooms//timeline".
		assertNull(OsgsPlugin.sanitizeRoomCode(null));
		assertNull(OsgsPlugin.sanitizeRoomCode(""));
		assertNull(OsgsPlugin.sanitizeRoomCode("   "));
		assertNull(OsgsPlugin.sanitizeRoomCode("...///"));
	}

	@Test
	public void roomCodeIsTruncatedToTheDocumentedMaximum()
	{
		final String long50 = new String(new char[50]).replace('\0', 'a');
		assertEquals(OsgsPlugin.ROOM_CODE_MAX_LENGTH, OsgsPlugin.sanitizeRoomCode(long50).length());
		// Truncation counts surviving characters, not typed ones: 30 legal chars with junk mixed in
		// still yields the first 24 legal ones.
		assertEquals("abcdefghijabcdefghijabcd",
			OsgsPlugin.sanitizeRoomCode("abcde.fghij abcde/fghij#abcdefghij"));
	}

	@Test
	public void sanitizedRoomCodesNeverContainAFirebaseIllegalCharacter()
	{
		final String code = OsgsPlugin.sanitizeRoomCode("Fri.day#2$[x]/night");
		assertEquals("friday2xnight", code);
		for (char illegal : new char[]{'.', '#', '$', '[', ']', '/'})
		{
			assertEquals("code must not contain " + illegal, -1, code.indexOf(illegal));
		}
	}

	private static JsonArray items(JsonObject... entries)
	{
		final JsonArray array = new JsonArray();
		for (JsonObject entry : entries)
		{
			array.add(entry);
		}
		return array;
	}

	/** Items with no ID — the shape a manually entered drop will always have. */
	private static JsonObject item(String name, int qty, long gp)
	{
		return OsgsPlugin.buildLootItem(name, qty, gp, 0);
	}
}

