import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import java.util.Map;
import java.util.regex.Matcher;
import org.junit.Test;

public class OsgsParsingTest
{
	private final Map<String, String> tracked = OsgsPlugin.buildTrackedBosses("Barrows, thermonuclear smoke devil");

	@Test
	public void killCountPatternParsesPresetBosses()
	{
		assertKill("Your Kree'arra kill count is: 47.", "Kree'arra", 47);
		assertKill("Your Vet'ion kill count is: 12.", "Vet'ion", 12);
		assertKill("Your Corporeal Beast kill count is: 3.", "Corporeal Beast", 3);
		assertKill("Your TzTok-Jad kill count is: 1.", "TzTok-Jad", 1);
		// "General Graardor" is covered by bandosMapsFromInGameNameToToolDisplayName — its
		// canonical name differs from the captured chat text, so it can't use this helper.
	}

	@Test
	public void killCountPatternParsesExpandedBosses()
	{
		// The production miss that prompted the list sync.
		assertKill("Your Alchemical Hydra kill count is: 370.", "Alchemical Hydra", 370);
		// Hyphenated, apostrophed and multi-word names all survive the greedy (.+) group.
		assertKill("Your TzKal-Zuk kill count is: 2.", "TzKal-Zuk", 2);
		assertKill("Your K'ril Tsutsaroth kill count is: 88.", "K'ril Tsutsaroth", 88);
		assertKill("Your Calvar'ion kill count is: 15.", "Calvar'ion", 15);
		assertKill("Your Phosani's Nightmare kill count is: 9.", "Phosani's Nightmare", 9);

		// Regex-only check: this fixture also defines "thermonuclear smoke devil" as a custom
		// boss, and custom entries deliberately override presets, so the canonical name here is
		// the user's spelling rather than the preset's. See customBossesOverridePresets.
		final Matcher m = OsgsPlugin.KILL_COUNT_PATTERN
			.matcher("Your Thermonuclear Smoke Devil kill count is: 1234.");
		assertTrue(m.find());
		assertEquals("Thermonuclear Smoke Devil", m.group(1));
		assertEquals(1234, Integer.parseInt(m.group(2)));
	}

	@Test
	public void killCountPatternIgnoresUnrelatedMessages()
	{
		assertTrue("no kill line should not match",
			!OsgsPlugin.KILL_COUNT_PATTERN.matcher("Welcome to RuneScape.").find());
	}

	@Test
	public void activitiesWithoutKillCountWordingAreIgnoredNotMisparsed()
	{
		// Raids/skilling activities announce completions differently. They must not match the
		// kill-count pattern at all; they are tracked through loot events instead.
		assertNoKillMatch("Your completed Chambers of Xeric count is: 5.");
		assertNoKillMatch("Your completed Theatre of Blood count is: 5.");
		assertNoKillMatch("Your completed Tombs of Amascut count is: 5.");
		assertNoKillMatch("Your subdued Wintertodt count is: 5.");
		assertNoKillMatch("Your Barrows chest count is: 5.");
		assertNoKillMatch("Your Gauntlet completion count is: 5.");
	}

	@Test
	public void bandosMapsFromInGameNameToToolDisplayName()
	{
		// The tool's display name is "Bandos"; the game says "General Graardor".
		assertEquals("Bandos", OsgsPlugin.normalizeBoss(tracked, "General Graardor"));
		assertEquals("Bandos", OsgsPlugin.normalizeBoss(tracked, "Bandos"));

		final Matcher m = OsgsPlugin.KILL_COUNT_PATTERN.matcher("Your General Graardor kill count is: 500.");
		assertTrue(m.find());
		assertEquals("Bandos", OsgsPlugin.normalizeBoss(tracked, m.group(1)));
	}

	@Test
	public void lootEventNamesResolveToToolDisplayNames()
	{
		// Names RuneLite's loot tracker actually posts, mapped onto the tool's display names.
		assertEquals("Lunar Chests", OsgsPlugin.normalizeBoss(tracked, "Lunar Chest"));
		assertEquals("Sol Heredit", OsgsPlugin.normalizeBoss(tracked, "Fortis Colosseum"));
		assertEquals("Wintertodt", OsgsPlugin.normalizeBoss(tracked, "Supply crate (Wintertodt)"));
		assertEquals("Wintertodt", OsgsPlugin.normalizeBoss(tracked, "Reward cart (Wintertodt)"));
		assertEquals("Tempoross", OsgsPlugin.normalizeBoss(tracked, "Reward pool (Tempoross)"));
		assertEquals("Tempoross", OsgsPlugin.normalizeBoss(tracked, "Casket (Tempoross)"));
		assertEquals("Grotesque Guardians", OsgsPlugin.normalizeBoss(tracked, "Dusk"));
		assertEquals("The Gauntlet", OsgsPlugin.normalizeBoss(tracked, "Crystalline Hunllef"));
		assertEquals("The Corrupted Gauntlet", OsgsPlugin.normalizeBoss(tracked, "Corrupted Hunllef"));
		assertEquals("Nightmare", OsgsPlugin.normalizeBoss(tracked, "The Nightmare"));

		// Raids post loot under the base name only, with no difficulty suffix.
		assertEquals("Chambers of Xeric", OsgsPlugin.normalizeBoss(tracked, "Chambers of Xeric"));
		assertEquals("Theatre of Blood", OsgsPlugin.normalizeBoss(tracked, "Theatre of Blood"));
		assertEquals("Tombs of Amascut", OsgsPlugin.normalizeBoss(tracked, "Tombs of Amascut"));
	}

	@Test
	public void expandedPresetsAreAllTracked()
	{
		// Spot-check across the appended half of the list, including the previously-missing boss.
		final Map<String, String> presetsOnly = OsgsPlugin.buildTrackedBosses("");
		for (String name : new String[]{
			"Alchemical Hydra", "Amoxliatl", "Araxxor", "Artio", "Commander Zilyana",
			"Kalphite Queen", "King Black Dragon", "Nex", "Scurrius", "Vardorvis",
			"Venenatis", "Yama", "Zalcano", "The Whisperer", "The Royal Titans",
			"Doom of Mokhaiotl", "Shellbane Gryphon", "Thermonuclear Smoke Devil"})
		{
			assertEquals(name, OsgsPlugin.normalizeBoss(presetsOnly, name));
		}
		// Previously-working bosses must not regress.
		for (String name : new String[]{
			"Kree'arra", "Vet'ion", "Vorkath", "Zulrah", "Tormented Demon", "Abyssal Sire",
			"Cerberus", "Kraken", "TzTok-Jad", "Sarachnis", "Chaos Elemental", "Dagannoth Rex",
			"Corporeal Beast", "Nightmare"})
		{
			assertEquals(name, OsgsPlugin.normalizeBoss(presetsOnly, name));
		}
	}

	@Test
	public void normalizeBossIsCaseInsensitiveAndScoped()
	{
		assertEquals("Kree'arra", OsgsPlugin.normalizeBoss(tracked, "kree'arra"));
		assertEquals("Zulrah", OsgsPlugin.normalizeBoss(tracked, "ZULRAH"));
		// The "Custom" placeholder from the preset list is never a real match.
		assertNull(OsgsPlugin.normalizeBoss(tracked, "Custom"));
		// Untracked NPCs (skilling, random drops) are ignored.
		assertNull(OsgsPlugin.normalizeBoss(tracked, "Goblin"));
	}

	@Test
	public void customBossesAreTracked()
	{
		assertEquals("Barrows", OsgsPlugin.normalizeBoss(tracked, "barrows"));
		assertEquals("thermonuclear smoke devil",
			OsgsPlugin.normalizeBoss(tracked, "Thermonuclear Smoke Devil"));
	}

	@Test
	public void customBossesOverridePresetsAndAliases()
	{
		// Custom names are applied last, so a user can rename a preset ("Thermonuclear Smoke
		// Devil") or repoint an alias ("Barrows" would otherwise resolve to "Barrows Chests").
		assertEquals("Barrows Chests", OsgsPlugin.normalizeBoss(
			OsgsPlugin.buildTrackedBosses(""), "Barrows"));
		assertEquals("Barrows", OsgsPlugin.normalizeBoss(tracked, "Barrows"));
	}

	private void assertNoKillMatch(String message)
	{
		assertTrue("should not match the kill-count pattern: " + message,
			!OsgsPlugin.KILL_COUNT_PATTERN.matcher(message).find());
	}

	private void assertKill(String message, String expectedBoss, int expectedKc)
	{
		final Matcher m = OsgsPlugin.KILL_COUNT_PATTERN.matcher(message);
		assertTrue("expected a match for: " + message, m.find());
		assertEquals(expectedBoss, m.group(1));
		assertEquals(expectedKc, Integer.parseInt(m.group(2)));
		assertEquals(expectedBoss, OsgsPlugin.normalizeBoss(tracked, m.group(1)));
	}
