/**
 * Guards the property that {@link OsgsLootPayloadTest} structurally cannot: that every writer
 * actually <em>routes through</em> {@link OsgsPlugin#pathRoot(boolean, String)}.
 * <p>
 * Testing {@code pathRoot()} in isolation proves the resolver is correct; it proves nothing about
 * a caller that never asks it. A writer left holding the old hardcoded root would keep every
 * resolver test green while silently writing outside the room. So this drives the writers
 * themselves and asserts on where they land.
 * <p>
 * Two layers, because neither alone is sufficient:
 * <ol>
 *     <li>{@link #everyWriterLandsUnderTheRoomRoot()} and friends <em>execute</em> all three
 *     writers against a recording {@link FirebaseClient} and assert the resulting paths. This
 *     catches a writer that resolves its root wrongly.</li>
 *     <li>{@link #theWriterSetIsExactlyTheOneThisTestDrives()} scans the source for
 *     {@code fb.post(} / {@code fb.put(} call sites, because reflection can only exercise writers
 *     it already knows about — it cannot discover a fourth one someone adds later.</li>
 * </ol>
 */
public class OsgsWritePathTest
{
	private static final String PLAYER = "Golddcaleb";

	/** Deliberately unsanitized: a capital, spaces and a digit, so the sanitizer has to fire. */
	private static final String RAW_ROOM_CODE = "Test Room 1";
	private static final String SANITIZED = "testroom1";

	/** One recorded Firebase write. */
	private static final class Write
	{
		private final String method;
		private final String path;

		private Write(String method, String path)
		{
			this.method = method;
			this.path = path;
		}

		@Override
		public String toString()
		{
			return method + " " + path;
		}
	}

	/** Stands in for the real client and records where each write was aimed. */
	private static final class RecordingFirebase extends FirebaseClient
	{
		private final List<Write> writes = new ArrayList<>();

		private RecordingFirebase()
		{
			// Any non-blank base url makes isConfigured() true; no request is ever sent.
			super(null, "https://osgst-test-default-rtdb.firebaseio.com", "");
		}

		@Override
		void post(String path, String json)
		{
			writes.add(new Write("POST", path));
		}

		@Override
		void put(String path, String json)
		{
			writes.add(new Write("PUT", path));
		}
	}

	/**
	 * Drives all three writers with the given config and returns where they aimed, in a fixed
	 * order: timeline, presence, startMarker.
	 */
	private static List<Write> driveEveryWriter(boolean dev, String roomCode) throws Exception
	{
		final OsgsPlugin plugin = new OsgsPlugin();
		final RecordingFirebase fb = new RecordingFirebase();

		set(plugin, "firebase", fb);
		set(plugin, "playerName", PLAYER);
		set(plugin, "config", new OsgsConfig()
		{
			@Override
			public String roomCode()
			{
				return roomCode;
			}

			@Override
			public boolean devPaths()
			{
				return dev;
			}
		});
		// markSessionStart() confirms itself in game chat; swallow that so no Client is needed.
		set(plugin, "clientThread", new ClientThread()
		{
			@Override
			public void invoke(Runnable r)
			{
				// Intentionally not run: the chat message is not what this test is about.
			}
		});

		invoke(plugin, "postTimeline", new Class<?>[]{JsonObject.class}, new JsonObject());
		invoke(plugin, "sendHeartbeat", new Class<?>[0]);
		invoke(plugin, "markSessionStart", new Class<?>[0]);

		assertEquals("expected exactly one write per writer", 3, fb.writes.size());
		return fb.writes;
	}

	private static void set(OsgsPlugin plugin, String field, Object value) throws Exception
	{
		final Field f = OsgsPlugin.class.getDeclaredField(field);
		f.setAccessible(true);
		f.set(plugin, value);
	}

	private static void invoke(OsgsPlugin plugin, String name, Class<?>[] types, Object... args)
		throws Exception
	{
		final Method m = OsgsPlugin.class.getDeclaredMethod(name, types);
		m.setAccessible(true);
		m.invoke(plugin, args);
	}

	@Test
	public void everyWriterLandsUnderTheRoomRootWhenARoomCodeIsSet() throws Exception
	{
		// The regression this exists for: one writer keeping the legacy root while the others move.
		final List<Write> writes = driveEveryWriter(false, RAW_ROOM_CODE);

		assertEquals(
			Arrays.asList(
				"POST rooms/testroom1/timeline",
				"PUT rooms/testroom1/presence/" + PLAYER,
				"PUT rooms/testroom1/session/startMarker"),
			toStrings(writes));

		for (Write w : writes)
		{
			assertTrue(w + " must be under the room root", w.path.startsWith("rooms/" + SANITIZED + "/"));
			assertTrue(w + " must not touch the live root", !w.path.startsWith("gamenight/"));
			assertTrue(w + " must not touch the dev root", !w.path.startsWith("gamenight_dev/"));
		}
	}

	@Test
	public void aRoomCodeStillWinsWhenTheDevToggleIsAlsoOn() throws Exception
	{
		// Documented precedence, asserted at the writers rather than at the resolver: the dev
		// toggle must not divert one writer to a fourth root while the others stay in the room.
		for (Write w : driveEveryWriter(true, RAW_ROOM_CODE))
		{
			assertTrue(w + " must stay in the room", w.path.startsWith("rooms/" + SANITIZED + "/"));
		}
	}

	@Test
	public void everyWriterKeepsTheLegacyRootWhenTheRoomCodeIsBlank() throws Exception
	{
		// The upgrade-safety proof: a user who never touches the new field writes exactly where
		// v1.2.0 wrote, from every writer.
		assertEquals(
			Arrays.asList(
				"POST gamenight/plugin/timeline",
				"PUT gamenight/plugin/presence/" + PLAYER,
				"PUT gamenight/plugin/session/startMarker"),
			toStrings(driveEveryWriter(false, "")));
	}

	@Test
	public void everyWriterFollowsTheDevToggleWhenTheRoomCodeIsBlank() throws Exception
	{
		assertEquals(
			Arrays.asList(
				"POST gamenight_dev/plugin/timeline",
				"PUT gamenight_dev/plugin/presence/" + PLAYER,
				"PUT gamenight_dev/plugin/session/startMarker"),
			toStrings(driveEveryWriter(true, "")));
	}

	@Test
	public void aRoomCodeThatSanitizesAwayFallsBackFromEveryWriter() throws Exception
	{
		// "rooms//timeline" from any writer would be a silently broken path, not a visible error.
		for (Write w : driveEveryWriter(false, "  ...///  "))
		{
			assertTrue(w + " must fall back to the legacy root", w.path.startsWith("gamenight/plugin/"));
			assertTrue(w + " must not contain an empty segment", !w.path.contains("//"));
		}
	}

	/**
	 * The reflection tests above can only drive writers they were told about. This one reads the
	 * source and fails if the set of {@code fb.post(} / {@code fb.put(} call sites has changed, so
	 * a newly added writer cannot slip past unexercised.
	 * <p>
	 * Skipped rather than failed when the source tree is not on disk, so a build run from an
	 * unexpected working directory — the Plugin Hub builds from its own clone — cannot fail CI on
	 * a file-location detail. The protection that matters is local, where the mistake gets made.
	 */
	@Test
	public void theWriterSetIsExactlyTheOneThisTestDrives() throws IOException
	{
		final Path source = Paths.get("src/main/java/com/osgst/OsgsPlugin.java");
		Assume.assumeTrue("source tree not on disk; skipping the call-site scan",
			Files.isReadable(source));

		final Pattern writeCall = Pattern.compile("fb\\.(post|put)\\(\\s*([A-Za-z0-9_]+)");
		final Matcher m = writeCall.matcher(
			new String(Files.readAllBytes(source), StandardCharsets.UTF_8));

		final List<String> callSites = new ArrayList<>();
		while (m.find())
		{
			callSites.add(m.group(1) + " <- " + m.group(2));
		}

		assertEquals(
			"The set of Firebase writers changed. Every writer must resolve its root through a "
				+ "path*() helper, and every writer must be driven by driveEveryWriter() above — "
				+ "add the new one to both, then update this expectation.",
			Arrays.asList(
				"post <- pathTimeline",
				"put <- pathPresence",
				"put <- pathStartMarker"),
			callSites);

		for (String callSite : callSites)
		{
			if (!callSite.contains("<- path"))
			{
				fail("writer builds its own path instead of calling a path*() helper: " + callSite);
			}
		}
	}

	private static List<String> toStrings(List<Write> writes)
	{
		final List<String> out = new ArrayList<>();
		for (Write w : writes)
		{
			out.add(w.toString());
		}
		return out;
	}
}
